$(function () {
  const CURRENT_USER_KEY = "currentUser";

  function parseStoredUser(value) {
    if (!value) return null;
    const parts = value.split("|").map(decodeURIComponent);
    if (parts.length < 4 || !parts[0]) return null;

    return {
      id: Number(parts[0]),
      name: parts[1] || "",
      email: parts[2] || "",
      role: parts[3] || "user"
    };
  }

  function serializeUser(user) {
    return [user.id, user.name || "", user.email || "", user.role || "user"]
      .map((part) => encodeURIComponent(part))
      .join("|");
  }

  function parseUserHtml(html) {
    const $user = $("<div>").html(html).find(".auth-user").first();
    if (!$user.length) return null;

    return {
      id: Number($user.data("id")),
      name: $user.data("name") || "",
      email: $user.data("email") || "",
      role: $user.data("role") || "user"
    };
  }

  function parseErrorHtml(html, fallback) {
    const $error = $("<div>").html(html).find(".php-error").first();
    return $error.data("error") || $error.text() || fallback;
  }

  function readStoredUser() {
    return parseStoredUser(localStorage.getItem(CURRENT_USER_KEY));
  }

  function setCurrentUser(user) {
    if (user) {
      localStorage.setItem(CURRENT_USER_KEY, serializeUser(user));
    } else {
      localStorage.removeItem(CURRENT_USER_KEY);
    }

    window.__currentUser = user || null;
    $(document).trigger("auth:changed", [window.__currentUser]);
  }

  function setError($input) {
    $input.addClass("error").removeClass("valid");
  }

  function setValid($input) {
    $input.removeClass("error").addClass("valid");
  }

  function clearState($input) {
    $input.removeClass("error valid");
  }

  function showMessage(selector, text) {
    $(selector).text(text);
  }

  function showNotification(text) {
    const $note = $("#notification");
    if (!$note.length) return;

    $note.text(text).addClass("show");
    setTimeout(() => $note.removeClass("show"), 3000);
  }

  function renderUserUI(user) {
    if (user) {
      $("#authButtons").hide();
      $("#userInfo").show();

      $("#userName").text(user.name || "");
      $("#userRole").text(user.role === "admin" ? "(Администратор)" : "(Пользователь)");

      if (user.role === "admin") {
        $(".cart-btn").hide();
      } else {
        $(".cart-btn").show();
      }

      $("#logoutBtn").off("click").on("click", function () {
        $.ajax({
          url: "api/auth/logout",
          type: "POST"
        }).always(function () {
          setCurrentUser(null);
          location.reload();
        });
      });
    } else {
      $("#authButtons").show();
      $("#userInfo").hide();
      $(".cart-btn").hide();
    }
  }

  function syncUserFromServer() {
    return $.ajax({
      url: "api/auth/me",
      type: "GET"
    }).then(function (html) {
      const user = parseUserHtml(html);
      setCurrentUser(user);
      renderUserUI(user);
      return user;
    }).catch(function () {
      setCurrentUser(null);
      renderUserUI(null);
      return null;
    });
  }

  // init user state
  const cachedUser = readStoredUser();
  window.__currentUser = cachedUser;
  renderUserUI(cachedUser);
  syncUserFromServer();

  // register
  $("#registerForm").on("submit", function (e) {
    e.preventDefault();

    const $name = $("#name");
    const $password = $("#password");
    const $confirm = $("#confirmPassword");
    const $email = $("#email");

    let hasError = false;

    clearState($name);
    clearState($password);
    clearState($confirm);
    clearState($email);

    if (($name.val() || "").trim().length < 2) {
      setError($name);
      hasError = true;
    } else {
      setValid($name);
    }

    if (($password.val() || "").length < 8) {
      setError($password);
      hasError = true;
    } else {
      setValid($password);
    }

    if ($password.val() !== $confirm.val()) {
      setError($confirm);
      hasError = true;
    } else {
      setValid($confirm);
    }

    if (!($email.val() || "").includes("@")) {
      setError($email);
      hasError = true;
    } else {
      setValid($email);
    }

    if (hasError) {
      showMessage("#regMessage", "Проверьте поля формы");
      return;
    }

    $.ajax({
      url: "api/auth/register",
      type: "POST",
      data: {
        name: $name.val(),
        email: $email.val(),
        password: $password.val()
      },
      success: function (html) {
        const error = parseErrorHtml(html, "");
        if (error) {
          showMessage("#regMessage", error);
          if (error.toLowerCase().includes("email")) {
            setError($email);
          }
          return;
        }

        setCurrentUser(parseUserHtml(html));
        showNotification("Регистрация прошла успешно");
        setTimeout(function () {
          window.location.href = "cars";
        }, 700);
      },
      error: function (xhr) {
        showMessage("#regMessage", parseErrorHtml(xhr.responseText, "Ошибка регистрации"));
      }
    });
  });

  // login
  $("#loginForm").on("submit", function (e) {
    e.preventDefault();

    const $email = $(this).find("[name='email']");
    const $password = $(this).find("[name='password']");

    clearState($email);
    clearState($password);

    if (!($email.val() || "").includes("@")) {
      setError($email);
      showMessage("#loginMessage", "Некорректный email");
      return;
    }
    setValid($email);

    if (($password.val() || "").length < 8) {
      setError($password);
      showMessage("#loginMessage", "Пароль должен быть не менее 8 символов");
      return;
    }
    setValid($password);

    $.ajax({
      url: "api/auth/login",
      type: "POST",
      data: {
        email: $email.val(),
        password: $password.val()
      },
      success: function (html) {
        const error = parseErrorHtml(html, "");
        if (error) {
          showMessage("#loginMessage", error);
          return;
        }

        setCurrentUser(parseUserHtml(html));
        showNotification("Вход выполнен");
        setTimeout(function () {
          window.location.href = "cars";
        }, 700);
      },
      error: function (xhr) {
        showMessage("#loginMessage", parseErrorHtml(xhr.responseText, "Ошибка при входе"));
      }
    });
  });

  $("input").on("input", function () {
    $(this).removeClass("error");
  });
});

let carsData = [];
$(document).ready(function () {
  const { createApp } = Vue;
  const CART_KEY = 'cart';
  const CARS_URL = 'api/cars';
  const ADMIN_CARS_URL = 'api/admin/cars';
  const ADMIN_USERS_URL = 'api/admin/users';
  let currentSort = 'new';
  let isSubmittingOrder = false;
  let adminUsersMap = {};

  function parsePackedList(value) {
    return (value || '').toString().split('|').map((item) => item.trim()).filter(Boolean);
  }

  function parseStoredUser(value) {
    if (!value) return null;
    const parts = value.split('|').map(decodeURIComponent);
    if (parts.length < 4 || !parts[0]) return null;
    return {
      id: Number(parts[0]),
      name: parts[1] || '',
      email: parts[2] || '',
      role: parts[3] || 'user'
    };
  }

  function serializeCart(cart) {
    return cart.map((item) => [
      item.id,
      item.qty,
      item.price,
      item.title || '',
      item.img || ''
    ].map((part) => encodeURIComponent(part)).join('~')).join('|');
  }

  function parseCart(value) {
    if (!value) return [];
    return value.split('|').filter(Boolean).map((chunk) => {
      const parts = chunk.split('~').map(decodeURIComponent);
      return {
        id: Number(parts[0]),
        qty: Number(parts[1]) || 1,
        price: Number(parts[2]) || 0,
        title: parts[3] || '',
        img: parts[4] || ''
      };
    }).filter((item) => item.id && item.price);
  }

  function parseErrorHtml(html, fallback) {
    const $error = $('<div>').html(html).find('.php-error').first();
    return $error.data('error') || $error.text() || fallback;
  }

  function getCart() {
    return parseCart(localStorage.getItem(CART_KEY));
  }

  function saveCart(cart) {
    localStorage.setItem(CART_KEY, serializeCart(cart));
  }

  function formatPrice(num) {
    return '$' + num.toLocaleString();
  }

  function getCurrentUser() {
    if (window.__currentUser) {
      return window.__currentUser;
    }

    return parseStoredUser(localStorage.getItem('currentUser'));
  }

  function isAdmin() {
    const user = getCurrentUser();
    return user && user.role === 'admin';
  }

  function isUser() {
    const user = getCurrentUser();
    return user && user.role === 'user';
  }

  function normalizeImageUrl(imageUrl) {
    const raw = (imageUrl || '').toString().trim();
    if (!raw) return 'images/no-image.jpg';
    if (/^https?:\/\//i.test(raw)) return raw;

    const normalized = raw.replace(/\\/g, '/');
    const fileName = normalized.split('/').filter(Boolean).pop();
    return fileName ? `images/${fileName}` : 'images/no-image.jpg';
  }

  function buildImageSet(primaryImageUrl, imageUrls = []) {
    const normalizedFromArray = Array.isArray(imageUrls)
      ? imageUrls.map(normalizeImageUrl).filter(Boolean)
      : [];

    const normalizedPrimary = normalizeImageUrl(primaryImageUrl);
    const unique = [];

    function pushUnique(url) {
      if (!url || unique.includes(url)) return;
      unique.push(url);
    }

    pushUnique(normalizedPrimary);
    normalizedFromArray.forEach(pushUnique);

    const first = unique[0] || 'images/no-image.jpg';
    if (!/^https?:\/\//i.test(first)) {
      const match = first.match(/^(.*)_\d+(\.[^.]+)$/i);
      if (match) {
        const base = match[1];
        const ext = match[2];
        for (let i = 1; i <= 3; i += 1) {
          pushUnique(`${base}_${i}${ext}`);
        }
      }
    }

    return unique.slice(0, 3);
  }

  function mapCarFromCard(card) {
    const $card = $(card);
    const imageUrl = $card.attr('data-image-url') || '';
    const features = parsePackedList($card.attr('data-features'));
    const services = parsePackedList($card.attr('data-services'));
    const images = parsePackedList($card.attr('data-images'));

    return {
      id: Number($card.data('id')),
      title: `${$card.data('brand') || ''} ${$card.data('model') || ''}`.trim(),
      price: parseFloat($card.data('price')) || 0,
      images: buildImageSet(imageUrl, images),
      brand: $card.data('brand') || '',
      model: $card.data('model') || '',
      year: $card.data('year') || '',
      image_url: normalizeImageUrl(imageUrl),
      keywords: [],
      features,
      color: ($card.data('color') || '').toString().toLowerCase(),
      services
    };
  }

  function loadCarsFromServer() {
    if (!$('.products-grid').length) return;

    $.ajax({
      url: CARS_URL,
      success: function (html) {
        const error = parseErrorHtml(html, '');
        if (error) {
          console.error('Некорректный ответ при загрузке машин');
          return;
        }

        const $cards = $('<div>').html(html).find('.card');
        carsData = $cards.map((_, card) => mapCarFromCard(card)).get();
        sortCars(currentSort);
        ensureAdminTools();
      },
      error: function() {
        console.error('Ошибка загрузки машин');
      }
    });
  }

  loadCarsFromServer();

  function renderCars(cars) {
    const $grid = $('.products-grid');
    $grid.empty();

    cars.forEach(car => {
      const imageSet = buildImageSet(car.image_url, car.images);
      const slidesMarkup = imageSet.map((imageSrc) => `
            <div class="slide">
              <img src="${imageSrc}" alt="${car.title}">
            </div>
      `).join('');
      
      const adminControls = isAdmin()
        ? `<div class="admin-controls">
             <button class="admin-edit-btn">Изменить</button>
             <button class="admin-delete-btn">Удалить</button>
           </div>`
        : '';
      const userControls = isUser() ? `<div class="vue-add-wrapper"></div>`: '';
      
      const card = `
        <div class="card" data-id="${car.id}">
          <div class="card-slider">
            ${slidesMarkup}
          </div>
          <h5>${car.title}</h5>
          <div class="price">${formatPrice(car.price)}</div>
          ${userControls}
          ${adminControls}
        </div>
      `;
      $grid.append(card);
    });
    mountVueAddButtons();
    ensureAdminTools();
  }

  $(document).on('click', '.admin-delete-btn', function () {
    if (!isAdmin()) return;

    const $card = $(this).closest('.card');
    const id = Number($card.data('id'));
    if (!id) return;

    if (!window.confirm('Удалить автомобиль из базы данных?')) {
      return;
    }

    $.ajax({
      url: ADMIN_CARS_URL,
      type: 'POST',
      data: {
        action: 'delete',
        id
      },
      success: function (html) {
        const error = parseErrorHtml(html, '');
        if (error) {
          alert(error || 'Не удалось удалить автомобиль');
          return;
        }

        loadCarsFromServer();
      },
      error: function (xhr) {
        alert(parseErrorHtml(xhr.responseText, 'Не удалось удалить автомобиль'));
      }
    });
  });

  function ensureAdminTools() {
    if (!isAdmin() || !$('.products-grid').length) return;

    if (!$('#adminToolbar').length) {
      $('.search-row').append(`
        <div id="adminToolbar" class="admin-toolbar">
          <button type="button" id="adminAddCarBtn" class="admin-btn">⚙️ Добавить авто</button>
          <button type="button" id="adminManageUsersBtn" class="admin-btn">👥 Управлять пользователями</button>
        </div>
      `);
    }

    if (!$('#adminCarModal').length) {
      $('body').append(`
        <div class="admin-modal" id="adminCarModal">
          <div class="admin-modal__panel">
            <div class="admin-modal__head">
              <h3 id="adminCarModalTitle">Автомобиль</h3>
              <button type="button" class="admin-modal__close" data-close-modal="#adminCarModal">&times;</button>
            </div>
            <form id="adminCarForm" class="admin-form">
              <input type="hidden" name="id" value="">
              <div class="admin-form__row">
                <input type="text" name="brand" placeholder="Марка" required>
                <input type="text" name="model" placeholder="Модель" required>
              </div>
              <div class="admin-form__row">
                <input type="number" name="year" placeholder="Год">
                <input type="number" step="0.01" min="0" name="price" placeholder="Цена" required>
              </div>
              <input type="text" name="image_url" placeholder="Ссылка/путь к основному изображению">
              <input type="text" name="color" placeholder="Цвет (например: Чёрный, Красный)">
              <textarea name="features" placeholder="Характеристики (через ; например: AWD; МКПП; Кожаный салон)"></textarea>
              <textarea name="services" placeholder="Услуги (через ; например: Алькантара; Карбон пакет)"></textarea>
              <div class="admin-form__actions">
                <button type="button" data-close-modal="#adminCarModal">Отмена</button>
                <button type="submit">Сохранить</button>
              </div>
            </form>
          </div>
        </div>
      `);
    }

    if (!$('#adminUsersModal').length) {
      $('body').append(`
        <div class="admin-modal" id="adminUsersModal">
          <div class="admin-modal__panel">
            <div class="admin-modal__head">
              <h3>Пользователи</h3>
              <button type="button" class="admin-modal__close" data-close-modal="#adminUsersModal">&times;</button>
            </div>
            <div class="admin-users-layout">
              <div>
                <table class="admin-users-table">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Имя</th>
                      <th>Email</th>
                      <th>Действие</th>
                    </tr>
                  </thead>
                  <tbody id="adminUsersRows"></tbody>
                </table>
              </div>
              <div>
                <form id="adminUserForm" class="admin-form">
                  <input type="hidden" name="id" value="">
                  <input type="text" name="name" placeholder="Имя" required>
                  <input type="email" name="email" placeholder="Email" required>
                  <input type="password" name="password" placeholder="Новый пароль (опционально)">
                  <label class="admin-form__checkbox">
                    <input type="checkbox" name="isAdmin" value="admin">
                    Предоставить доступ к админ панели
                  </label>
                  <div class="admin-form__actions">
                    <button type="submit">Сохранить пользователя</button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      `);
    }
  }

  function openModal(selector) {
    $(selector).addClass('show');
  }

  function closeModal(selector) {
    $(selector).removeClass('show');
  }

  function fillCarForm(car) {
    const $form = $('#adminCarForm');
    $form.find('[name="id"]').val(car ? car.id : '');
    $form.find('[name="brand"]').val(car ? car.brand : '');
    $form.find('[name="model"]').val(car ? car.model : '');
    $form.find('[name="year"]').val(car && car.year ? car.year : '');
    $form.find('[name="price"]').val(car ? car.price : '');
    $form.find('[name="image_url"]').val(car ? (car.image_url || '') : '');
    $form.find('[name="color"]').val(car ? (car.color || '') : '');
    $form.find('[name="features"]').val(car && car.features && car.features.length ? car.features.join('; ') : '');
    $form.find('[name="services"]').val(car && car.services && car.services.length ? car.services.join('; ') : '');
  }

  function loadAdminUsers() {
    $.ajax({
      url: ADMIN_USERS_URL,
      type: 'GET',
      success: function (html) {
        const error = parseErrorHtml(html, '');
        if (error) {
          alert(error || 'Не удалось загрузить пользователей');
          return;
        }

        adminUsersMap = {};
        $('#adminUsersRows').html(html);
        $('#adminUsersRows tr[data-user-id]').each(function () {
          const $row = $(this);
          const user = {
            id: Number($row.data('user-id')),
            name: $row.data('name') || '',
            email: $row.data('email') || '',
            role: $row.data('role') || 'user'
          };
          adminUsersMap[user.id] = user;
        });
      },
      error: function (xhr) {
        alert(parseErrorHtml(xhr.responseText, 'Не удалось загрузить пользователей'));
      }
    });
  }

  $(document).on('click', '#adminAddCarBtn', function () {
    $('#adminCarModalTitle').text('Добавить автомобиль');
    fillCarForm(null);
    openModal('#adminCarModal');
  });

  $(document).on('click', '.admin-edit-btn', function () {
    if (!isAdmin()) return;

    const id = Number($(this).closest('.card').data('id'));
    const car = carsData.find((item) => Number(item.id) === id);
    if (!car) {
      alert('Автомобиль не найден');
      return;
    }

    $('#adminCarModalTitle').text('Редактировать автомобиль');
    fillCarForm(car);
    openModal('#adminCarModal');
  });

  $(document).on('click', '#adminManageUsersBtn', function () {
    if (!isAdmin()) return;
    openModal('#adminUsersModal');
    loadAdminUsers();
  });

  $(document).on('click', '[data-close-modal]', function () {
    closeModal($(this).attr('data-close-modal'));
  });

  $(document).on('submit', '#adminCarForm', function (e) {
    e.preventDefault();

    const id = Number($(this).find('[name="id"]').val());
    const payload = {
      action: id ? 'update' : 'create',
      id: id || '',
      brand: $(this).find('[name="brand"]').val(),
      model: $(this).find('[name="model"]').val(),
      year: $(this).find('[name="year"]').val(),
      price: $(this).find('[name="price"]').val(),
      image_url: $(this).find('[name="image_url"]').val(),
      color: $(this).find('[name="color"]').val(),
      features: $(this).find('[name="features"]').val(),
      services: $(this).find('[name="services"]').val()
    };

    $.ajax({
      url: ADMIN_CARS_URL,
      type: 'POST',
      data: payload,
      success: function (html) {
        const error = parseErrorHtml(html, '');
        if (error) {
          alert(error || 'Ошибка сохранения автомобиля');
          return;
        }

        closeModal('#adminCarModal');
        loadCarsFromServer();
      },
      error: function (xhr) {
        alert(parseErrorHtml(xhr.responseText, 'Ошибка сохранения автомобиля'));
      }
    });
  });

  $(document).on('click', '.admin-user-edit', function () {
    const userId = Number($(this).data('user-id'));
    const user = adminUsersMap[userId];
    if (!user) return;

    const $form = $('#adminUserForm');
    $form.find('[name="id"]').val(user.id);
    $form.find('[name="name"]').val(user.name || '');
    $form.find('[name="email"]').val(user.email || '');
    $form.find('[name="password"]').val('');
    $form.find('[name="isAdmin"]').prop('checked', (user.role || 'user') === 'admin');
  });

  $(document).on('submit', '#adminUserForm', function (e) {
    e.preventDefault();

    const payload = {
      action: 'update',
      id: $(this).find('[name="id"]').val(),
      name: $(this).find('[name="name"]').val(),
      email: $(this).find('[name="email"]').val(),
      password: $(this).find('[name="password"]').val(),
      role: $(this).find('[name="isAdmin"]').is(':checked') ? 'admin' : 'user'
    };

    $.ajax({
      url: ADMIN_USERS_URL,
      type: 'POST',
      data: payload,
      success: function (html) {
        const error = parseErrorHtml(html, '');
        if (error) {
          alert(error || 'Ошибка сохранения пользователя');
          return;
        }

        alert('Пользователь обновлен');
        loadAdminUsers();
      },
      error: function (xhr) {
        alert(parseErrorHtml(xhr.responseText, 'Ошибка сохранения пользователя'));
      }
    });
  });

  $(document).on('auth:changed', function () {
    if ($('.products-grid').length) {
      loadCarsFromServer();
      ensureAdminTools();
    }
  });
  function sortCars(type) {
    let sorted = [...carsData];

    if (type === 'cheap') {
      sorted.sort((a, b) => a.price - b.price);
    }

    if (type === 'expensive') {
      sorted.sort((a, b) => b.price - a.price);
    }

    if (type === 'new') {
      sorted.sort((a, b) => {
        const yearA = Number(a.year) || 0;
        const yearB = Number(b.year) || 0;

        if (yearB !== yearA) {
          return yearB - yearA;
        }

        return b.id - a.id;
      });
    }

    renderCars(sorted);
  }

  $(document).on('change', '#sortSelect', function () {
    const sortType = $(this).val();
    currentSort = sortType;
    sortCars(currentSort);
  });

  $(document).on('jquery-add', '.add-to-order-btn', function () {
    const card = $(this).closest('.card');

    const item = {
      id: card.data('id'),
      title: card.find('h5').text(),
      price: parseInt(card.find('.price').text().replace(/\D/g, '')),
      img: card.find('img').first().attr('src')
    };

    const cart = getCart();
    const existing = cart.find(c => c.id === item.id);

    if (existing) {
      existing.qty += 1;
    } else {
      cart.push({
        ...item,
        qty: 1
      });
    }

    saveCart(cart);
    recalcCart();
  });
  
  function recalcCart() {
    const cart = getCart();
    let total = 0;

    cart.forEach(item => {
      total += item.price * item.qty;
    });


    const delivery  = total ? 5000  : 0;
    const insurance = total ? 12000 : 0;
    const customs   = total ? 8500  : 0;
    const finalSum  = total + delivery + insurance + customs;

    const isFinalPage = $('.step.completed').length === 2;

    if ($('#cartItems').length) {
      $('#cartCount').text(cart.length);
      
      const container = $('#cartItemsContainer');
      
      if (container.length === 0 && $('#cartItems').length) {
        $('#cartItems').append('<div id="cartItemsContainer"></div>');
      }
      
      $('#cartItemsContainer').empty();

      if (cart.length === 0) {
        $('#cartItemsContainer').html(`
          <div class="empty-cart">
            <h3>Ваша корзина пуста</h3>
            <a href="cars" class="btn-back-to-shop">Перейти к покупкам</a>
          </div>
        `);
      } else {
        cart.forEach((item, index) => {
          const normalizedItemImg = normalizeImageUrl(item.img);
          const showControls = !isFinalPage;
          
          const controlsBlock = showControls ? `
              <div class="item-qty">
                <button class="qty-btn minus" data-index="${index}">-</button>
                <span>${item.qty}</span>
                <button class="qty-btn plus" data-index="${index}">+</button>
              </div>
              <div class="vue-remove-wrapper" data-index="${index}"></div>` : ``;
          
          const row = `
            <div class="cart-item">
              ${controlsBlock}

              <div class="item-image">
                <img src="${normalizedItemImg}" alt="${item.title}">
              </div>
              <div class="item-info">
                <h3>${item.title}</h3>
                <div class="item-price">${formatPrice(item.price)}</div>
              </div>
            </div>
          `;
          $('#cartItemsContainer').append(row);
        });
      }

      $('#sumPrice').text(formatPrice(total));
      $('#delivery').text(formatPrice(delivery));
      $('#insurance').text(formatPrice(insurance));
      $('#customs').text(formatPrice(customs));
      $('#total').text(formatPrice(finalSum));
      
      if (cart.length === 0) {
        $('#checkoutBtn').hide();
      } else {
        $('#checkoutBtn').show();
      }
    }
    mountVueRemoveButtons();
  }


  function updateCartHeader() {
    const cart = getCart();
    $('#cartCount').text(cart.length);
  }

  function initCart() {
    const cart = getCart();

    if (cart.length > 0 && ($('#cartItems').length || $('#cartItemsContainer').length)) {
      console.log('Загружаем корзину из localStorage:', cart);
      recalcCart();
    }

    if ($('.products-grid').length) {
      updateCartHeader();
    }
  }

  // vue
  function mountVueAddButtons() {
    document.querySelectorAll('.vue-add-wrapper').forEach(wrapper => {
      if (wrapper.__vueMounted) return;
      wrapper.__vueMounted = true;

      createApp({
        data() {
          return {
            added: false
          };
        },
        computed: {
          text() {
            return this.added ? '✓ Добавлено' : 'Добавить в заказ';
          }
        },
        methods: {
          add() {
            if (this.added) return;
            this.added = true;

            $(this.$el)
              .closest('.card')
              .find('.add-to-order-btn')
              .trigger('jquery-add');

            setTimeout(() => {
              this.added = false;
            }, 1500);
          }
        },
        template: `
          <button
            class="add-to-order-btn"
            :disabled="added"
            @click="add"
          >
            {{ text }}
          </button>
        `
      }).mount(wrapper);
    });
  }

  function mountVueRemoveButtons() {
    document.querySelectorAll('.vue-remove-wrapper').forEach(wrapper => {
      if (wrapper.__vueMounted) return;
      wrapper.__vueMounted = true;

      createApp({
        methods: {
          remove() {
            const index = this.$el.parentElement.dataset.index;

            const cart = getCart();
            cart.splice(Number(index), 1);
            saveCart(cart);
            recalcCart();
          }
        },
        template: `<button class="item-remove" @click="remove">Удалить</button> `
      }).mount(wrapper);
    });
  }

  initCart();  
  recalcCart();

  function normalize(arr = []) {
    return arr.map(v =>
      v.toLowerCase().replace(/\s+/g, ' ').trim()
    );
  }

  function applyFilters() {
    let filtered = [...carsData];

    // keywords
    const keyword = $('.keywords input').val().toLowerCase().trim();
    if (keyword) {
      filtered = filtered.filter(car =>
        car.title.toLowerCase().includes(keyword) ||
        (car.keywords || []).some(k => k.toLowerCase().includes(keyword))
      );
    }

    // price
    const minPrice = +($('.price-filter .price-from').val() || 0);
    const maxPrice = +($('.price-filter .price-to').val() || 5000000);
    filtered = filtered.filter(car => car.price >= minPrice && car.price <= maxPrice);

    // features (including custom)
    const selectedFeatures = normalize(
      $('.filter-row input[type="checkbox"]:checked').map((_, el) => el.value).get()
    );

    if (selectedFeatures.length) {
      filtered = filtered.filter(car => {
        const carFeatures = normalize(car.features || []);
        return selectedFeatures.every(f => carFeatures.includes(f));
      });
    }

    // color (including custom)
    const colors = normalize(
      $('.dropdown:eq(0) input[type="checkbox"]:checked').map((_, el) => el.value).get()
    );

    if (colors.length) {
      filtered = filtered.filter(car =>
        colors.includes(((car.color || '').toString().toLowerCase()))
      );
    }

    // services (including custom)
    const services = normalize(
      $('.dropdown:eq(1) input[type="checkbox"]:checked').map((_, el) => el.value).get()
    );

    if (services.length) {
      filtered = filtered.filter(car =>
        services.every(s =>
          normalize(car.services || []).includes(s)
        )
      );
    }

    renderCars(filtered);
  }
  
  $(document).on('click', '.qty-btn.plus', function () {
    if ($('.step.completed').length === 2) return;
    
    const index = $(this).data('index');
    const cart = getCart();
    cart[index].qty += 1;
    saveCart(cart);
    recalcCart();
  });

  $(document).on('click', '.qty-btn.minus', function () {
    if ($('.step.completed').length === 2) return;
    
    const index = $(this).data('index');
    const cart = getCart();

    cart[index].qty -= 1;

    if (cart[index].qty <= 0) {
      cart.splice(index, 1);
    }

    saveCart(cart);
    recalcCart();
  });

  $('.add-btn').on('click', applyFilters);
  $('.filter-row input').on('change', applyFilters);
  $('.dropdown input').on('change', applyFilters);
  $('.price-filter input').on('input', applyFilters);

  // Handle custom filter additions
  $(document).on('click', '.add-custom-btn', function () {
    const type = $(this).data('type');
    let $input, $container;

    if (type === 'features') {
      $input = $('.custom-feature');
      $container = $('.filter-row');
    } else if (type === 'colors') {
      $input = $('.custom-color');
      $container = $('.dropdown:eq(0) .dropdown-list');
    } else if (type === 'services') {
      $input = $('.custom-service');
      $container = $('.dropdown:eq(1) .dropdown-list');
    }

    const value = $input.val().trim();

    if (value === '') {
      alert('Пожалуйста, введите значение');
      return;
    }

    // Check if this value already exists
    const exists = $container.find(`input[value="${value}"]`).length > 0;
    if (exists) {
      alert('Этот фильтр уже добавлен');
      return;
    }

    // Create new checkbox label
    const $newLabel = $(`<label><input type="checkbox" value="${value}">${value}</label>`);
    
    // Add listener to the new checkbox
    $newLabel.find('input').on('change', applyFilters);
    
    // Insert before the custom input section
    $container.find('.custom-input').before($newLabel);
    
    // Clear input
    $input.val('');
    
    // Apply filters
    applyFilters();
  });

  // Allow Enter key to add custom filter
  $(document).on('keypress', '.custom-feature, .custom-color, .custom-service', function (e) {
    if (e.which === 13) {
      e.preventDefault();
      $(this).parent().find('.add-custom-btn').click();
    }
  });

  $(document).on('click', '#checkoutBtn', function (e) {
    const user = getCurrentUser();
    const cart = getCart();

    if (!user) {
      e.preventDefault();
      alert('Пожалуйста, войдите в аккаунт для оформления заказа');
      window.location.href = 'login';
      return;
    }

    if (cart.length === 0) {
      e.preventDefault();
      alert('Корзина пуста');
    }
  });

  $(document).on('click', '#submitOrderBtn', function (e) {
    e.preventDefault();
    if (isSubmittingOrder) return;

    const user = getCurrentUser();
    
    if (!user) {
      alert('Пожалуйста, войдите в аккаунт для оформления заказа');
      window.location.href = 'login';
      return;
    }

    const cart = getCart();
    if (cart.length === 0) {
      alert('Корзина пуста');
      return;
    }

    isSubmittingOrder = true;
    const $button = $('#submitOrderBtn');
    $button.prop('disabled', true).text('Оформляем...');

    const startDateInput = $('input[name="startDate"], input[name="start_date"]').val();
    const endDateInput = $('input[name="endDate"], input[name="end_date"]').val();
    
    const today = new Date().toISOString().split('T')[0];
    const tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];
    
    const start_date = startDateInput || today;
    const end_date = endDateInput || tomorrow;
    const orderItems = {
      car_id: cart.map((item) => item.id),
      quantity: cart.map((item) => item.qty),
      unit_price: cart.map((item) => item.price)
    };

    $.ajax({
      url: 'api/orders/create',
      type: 'POST',
      data: {
        user_id: user.id,
        start_date: start_date,
        end_date: end_date,
        total_price: cart.reduce((sum, item) => sum + (item.price * item.qty), 0),
        car_id: orderItems.car_id,
        quantity: orderItems.quantity,
        unit_price: orderItems.unit_price
      },
      success: function(html) {
        const error = parseErrorHtml(html, '');
        if (!error) {
          const orderId = $('<div>').html(html).find('.order-result').data('order-id') || '';
          alert('Заказ успешно оформлен!\nНомер заказа: ' + orderId);
          localStorage.removeItem(CART_KEY);
          setTimeout(() => {
            window.location.href = 'cars';
          }, 1500);
        } else {
          alert('Ошибка при оформлении заказа:\n' + error);
          isSubmittingOrder = false;
          $button.prop('disabled', false).text('Подтвердить заказ');
        }
      },
      error: function(xhr) {
        isSubmittingOrder = false;
        $button.prop('disabled', false).text('Подтвердить заказ');
        alert('Ошибка при оформлении заказа:\n' + parseErrorHtml(xhr.responseText, 'Ошибка при оформлении заказа'));
      }
    });
  });
});


